/**
 * Generative hero widening.
 *
 * Takes the existing hero photographs in imgs/hero and produces wider versions in which
 * the original frame is carried through untouched and only the missing left/right space
 * is generated by an AI outpainting model.
 *
 *     [ AI band ][      ORIGINAL — pixel identical      ][ AI band ]
 *
 * The originals are never read-modify-written: outputs go to new `-wide.jpg` files, and
 * every run re-composites the original over the model output so the source always wins.
 *
 * Usage:
 *   npm run hero:expand -- --dry-run            geometry check, no API calls
 *   npm run hero:expand                          generate every hero that is missing
 *   npm run hero:expand -- --only villa-black-marble   one image
 *   npm run hero:expand -- --force               regenerate existing outputs
 *   npm run hero:expand -- --aspect 2.4          target hero aspect ratio
 *
 * Env (.env.local):
 *   IMAGE_AI_PROVIDER=openai | stability
 *   IMAGE_AI_API_KEY=...
 */

import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import sharp from "sharp";

const HERO_DIR = path.join(process.cwd(), "imgs", "hero");
const HERO_IMAGES = ["villa-marble-frontal", "villa-black-marble", "villa-stone-facade"];

/**
 * 2.4:1 covers every 21:9 / 24:10 ultrawide display. Because `object-fit: cover` scales to
 * fill the height, a viewport at least as wide as the original 16:9 aspect can only ever
 * trim generated band pixels — the original stays whole.
 */
const DEFAULT_ASPECT = 2.4;
const JPEG_QUALITY = 92;

// ---------------------------------------------------------------------------
// args + env
// ---------------------------------------------------------------------------

function parseArgs(argv) {
  const args = { aspect: DEFAULT_ASPECT, dryRun: false, force: false, only: null, provider: null };

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--dry-run") args.dryRun = true;
    else if (arg === "--force") args.force = true;
    else if (arg === "--aspect") args.aspect = Number(argv[++i]);
    else if (arg === "--only") args.only = argv[++i];
    else if (arg === "--provider") args.provider = argv[++i];
  }

  if (!Number.isFinite(args.aspect) || args.aspect <= 1) {
    throw new Error("--aspect must be a ratio greater than 1, e.g. 2.4");
  }

  return args;
}

function loadEnvLocal() {
  const envPath = path.join(process.cwd(), ".env.local");
  if (!existsSync(envPath)) return;

  for (const line of readFileSync(envPath, "utf8").split(/\r?\n/)) {
    const match = /^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/.exec(line);
    if (!match) continue;
    const value = match[2].replace(/^["']|["']$/g, "");
    if (!process.env[match[1]]) process.env[match[1]] = value;
  }
}

// ---------------------------------------------------------------------------
// geometry
// ---------------------------------------------------------------------------

/** Never crops, never scales: the original keeps its pixels and gains side padding. */
function planExpansion(width, height, aspect) {
  const targetWidth = Math.round(height * aspect);
  const extra = Math.max(0, targetWidth - width);
  const left = Math.floor(extra / 2);

  return {
    source: { width, height },
    target: { width: width + extra, height },
    padding: { left, right: extra - left },
    placement: { left, top: 0, width, height },
  };
}

// ---------------------------------------------------------------------------
// edge analysis → image-specific prompt
// ---------------------------------------------------------------------------

const luminanceOf = (r, g, b) => (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
const toHex = (r, g, b) =>
  `#${[r, g, b].map((c) => Math.round(c).toString(16).padStart(2, "0")).join("")}`;

/** Samples one edge strip and reports what physically sits there, band by band. */
async function readEdge(buffer, meta, edge) {
  const strip = Math.max(24, Math.round(meta.width * 0.04));
  const { data, info } = await sharp(buffer)
    .extract({
      left: edge === "left" ? 0 : meta.width - strip,
      top: 0,
      width: strip,
      height: meta.height,
    })
    .resize(8, 96, { fit: "fill" })
    .removeAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });

  const BANDS = 6;
  const rowsPerBand = Math.floor(info.height / BANDS);
  const bands = [];

  for (let band = 0; band < BANDS; band += 1) {
    let r = 0;
    let g = 0;
    let b = 0;
    let n = 0;
    const lums = [];

    for (let y = band * rowsPerBand; y < (band + 1) * rowsPerBand; y += 1) {
      for (let x = 0; x < info.width; x += 1) {
        const i = (y * info.width + x) * 3;
        r += data[i];
        g += data[i + 1];
        b += data[i + 2];
        lums.push(luminanceOf(data[i], data[i + 1], data[i + 2]));
        n += 1;
      }
    }

    r /= n;
    g /= n;
    b /= n;
    const lum = lums.reduce((t, v) => t + v, 0) / lums.length;
    const texture = lums.reduce((t, v) => t + Math.abs(v - lum), 0) / lums.length / 0.25;
    const position = (band + 0.5) / BANDS;

    let kind;
    if (g > r * 1.05 && g > b * 1.03) kind = "vegetation matching species, scale and density";
    else if (position < 0.5 && texture < 0.12 && lum > 0.3 && b >= r * 0.97)
      kind = "open sky with the same gradient and atmospheric haze";
    else if (position > 0.62 && texture < 0.2)
      kind = "the ground plane continuing along the existing perspective lines";
    else if (texture > 0.22) kind = "the same material detail at the same texture frequency";
    else kind = "the architectural surface continuing on the same vanishing lines";

    bands.push({ from: band / BANDS, to: (band + 1) / BANDS, kind, lum, hex: toHex(r, g, b) });
  }

  const merged = [];
  for (const band of bands) {
    const last = merged[merged.length - 1];
    if (last && last.kind === band.kind) last.to = band.to;
    else merged.push({ ...band });
  }

  return {
    edge,
    meanLuminance: bands.reduce((t, band) => t + band.lum, 0) / bands.length,
    summary: merged
      .map((b) => `${Math.round(b.from * 100)}–${Math.round(b.to * 100)}% continue ${b.kind}`)
      .join("; "),
  };
}

async function analyzeImage(buffer, meta) {
  const { data, info } = await sharp(buffer)
    .resize(256, null, { fit: "inside" })
    .removeAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });

  const buckets = new Map();
  let sumLum = 0;
  let sumR = 0;
  let sumB = 0;
  let leftLum = 0;
  let rightLum = 0;
  const third = Math.floor(info.width / 3);

  for (let y = 0; y < info.height; y += 1) {
    for (let x = 0; x < info.width; x += 1) {
      const i = (y * info.width + x) * 3;
      const [r, g, b] = [data[i], data[i + 1], data[i + 2]];
      const lum = luminanceOf(r, g, b);
      sumLum += lum;
      sumR += r;
      sumB += b;
      if (x < third) leftLum += lum;
      if (x >= info.width - third) rightLum += lum;

      const key = ((r >> 4) << 8) | ((g >> 4) << 4) | (b >> 4);
      const bucket = buckets.get(key);
      if (bucket) {
        bucket.r += r;
        bucket.g += g;
        bucket.b += b;
        bucket.n += 1;
      } else {
        buckets.set(key, { r, g, b, n: 1 });
      }
    }
  }

  const pixels = info.width * info.height;
  const meanLum = sumLum / pixels;
  const warmth = (sumR - sumB) / pixels;
  const lightDelta = (leftLum - rightLum) / (third * info.height);

  const [left, right] = await Promise.all([readEdge(buffer, meta, "left"), readEdge(buffer, meta, "right")]);

  return {
    palette: [...buckets.values()]
      .sort((a, b) => b.n - a.n)
      .slice(0, 5)
      .map(({ r, g, b, n }) => toHex(r / n, g / n, b / n)),
    meanLuminance: meanLum,
    temperature: warmth > 12 ? "warm" : warmth < -12 ? "cool" : "neutral",
    lighting:
      lightDelta > 0.045
        ? "the key light enters from the left, so shadows fall to the right"
        : lightDelta < -0.045
          ? "the key light enters from the right, so shadows fall to the left"
          : "the light is frontal and even",
    timeOfDay: meanLum < 0.18 ? "night" : meanLum < 0.32 ? "dusk" : warmth > 20 ? "golden hour" : "daylight",
    edges: { left, right },
  };
}

const NEGATIVE_PROMPT = [
  "new focal subject",
  "duplicated people",
  "duplicated buildings",
  "duplicated furniture",
  "duplicated vehicles",
  "mirrored composition",
  "repeating tiled pattern",
  "text",
  "signage",
  "logos",
  "watermark",
  "warped architecture",
  "broken perspective",
  "visible seam",
  "blur band",
  "oversmoothed plastic surfaces",
  "CGI render look",
  "illustration",
].join(", ");

function buildPrompt(analysis, plan, side) {
  const edge = side === "both" ? null : analysis.edges[side];

  const edgeLines = side === "both"
    ? [
        `LEFT EDGE (${plan.padding.left}px of new space) currently reads as — ${analysis.edges.left.summary}.`,
        `RIGHT EDGE (${plan.padding.right}px of new space) currently reads as — ${analysis.edges.right.summary}.`,
      ]
    : [`${side.toUpperCase()} EDGE (${plan.padding[side]}px of new space) currently reads as — ${edge.summary}.`];

  return [
    "Continue the existing environment naturally beyond the image boundaries.",
    `This is one continuous architectural photograph in ${analysis.timeOfDay}; you are widening the same exposure with a wider lens from the same tripod position, not creating a new photograph.`,
    "Preserve the exact visual language, lighting, perspective, materials, depth and photographic characteristics of the source.",
    "",
    "CONTINUITY:",
    `${analysis.lighting} — extend that same light and shadow logic outward with correct falloff.`,
    `Hold the palette ${analysis.palette.join(", ")}, the ${analysis.temperature} white balance, the grain and the depth of field.`,
    "Keep one vanishing point; every horizontal plane stays level across the join.",
    "",
    "EDGE CONTINUATION (the most important pixels are the ones touching the original):",
    ...edgeLines,
    "",
    "COMPOSITION RULES:",
    "Do not introduce a new focal subject.",
    "Do not alter the existing central composition.",
    "Create only the missing surrounding environment as background and mid-ground continuation.",
    "Never repeat, mirror or echo any object from the original frame. No new people, vehicles, products or signage.",
    "The transition must be undetectable: no seam, no brightness step, no repeated texture.",
  ].join("\n");
}

// ---------------------------------------------------------------------------
// context canvas + mask
// ---------------------------------------------------------------------------

/**
 * Seeds the empty side with the stretched, softened outer strip of the photo. Models anchor
 * on this far better than on a hard black frame — it is overwritten by generation anyway.
 */
async function stretchEdge(image, meta, side, width, height) {
  const strip = Math.min(8, meta.width);
  return sharp(image)
    .extract({ left: side === "left" ? 0 : meta.width - strip, top: 0, width: strip, height: meta.height })
    .resize(Math.max(1, width), Math.max(1, height), { fit: "fill" })
    .png()
    .toBuffer();
}

/** Grayscale mask: BLACK = original, protected. WHITE = generate. */
function buildMaskRaw(width, height, keep) {
  const raw = Buffer.alloc(width * height, 255);
  for (let y = keep.top; y < keep.top + keep.height; y += 1) {
    raw.fill(0, y * width + keep.left, y * width + keep.left + keep.width);
  }
  return raw;
}

// ---------------------------------------------------------------------------
// providers
// ---------------------------------------------------------------------------

function resolveProvider(requested) {
  const id = requested ?? process.env.IMAGE_AI_PROVIDER ?? "openai";
  const provider = PROVIDERS[id];
  if (!provider) {
    throw new Error(`Unknown IMAGE_AI_PROVIDER "${id}". Supported: ${Object.keys(PROVIDERS).join(", ")}.`);
  }
  return provider;
}

function requireApiKey(names) {
  for (const name of names) {
    if (process.env[name]) return process.env[name];
  }
  throw new Error(`Missing API key. Set ${names[0]} in .env.local (never commit it).`);
}

/**
 * OpenAI gpt-image-1 caps output at 1536×1024, so each side is generated in its own pass
 * using an aspect-matched window: the outer `pad` plus a wide strip of real context,
 * downscaled uniformly (no squeeze) and masked so only the pad is editable.
 */
const openai = {
  id: "openai",
  label: "OpenAI gpt-image-1 (images/edits)",
  async generateSides({ image, meta, plan, analysis, quality }) {
    const key = requireApiKey(["IMAGE_AI_API_KEY", "OPENAI_API_KEY"]);
    const bands = {};

    for (const side of ["left", "right"]) {
      const pad = plan.padding[side];
      if (pad <= 0) continue;

      const windowWidth = Math.round(meta.height * 1.5);
      const contextWidth = windowWidth - pad;

      if (contextWidth < windowWidth * 0.25) {
        throw new Error(
          `Expansion of ${pad}px is too large for a single ${side} pass at this image height. Lower --aspect.`,
        );
      }

      const contextLeft = side === "left" ? pad : 0;
      const contextRegion = {
        left: side === "left" ? 0 : meta.width - contextWidth,
        top: 0,
        width: contextWidth,
        height: meta.height,
      };

      const context = await sharp(image).extract(contextRegion).png().toBuffer();
      const filler = await stretchEdge(image, meta, side, pad, meta.height);

      const seeded = await sharp({
        create: {
          width: windowWidth,
          height: meta.height,
          channels: 3,
          background: analysis.palette[0] ?? "#808080",
        },
      })
        .composite([{ input: filler, left: side === "left" ? 0 : contextWidth, top: 0 }])
        .blur(8)
        .png()
        .toBuffer();

      const windowCanvas = await sharp(seeded)
        .composite([{ input: context, left: contextLeft, top: 0 }])
        .png()
        .toBuffer();

      // Uniform downscale — window aspect already equals the 1536×1024 request aspect.
      const requestWidth = 1536;
      const requestHeight = 1024;
      const ratio = requestWidth / windowWidth;
      const requestPad = Math.round(pad * ratio);

      const requestImage = await sharp(windowCanvas)
        .resize(requestWidth, requestHeight, { fit: "fill" })
        .png()
        .toBuffer();

      // gpt-image-1 edits the *transparent* areas of the mask.
      const maskRaw = buildMaskRaw(requestWidth, requestHeight, {
        left: side === "left" ? requestPad : 0,
        top: 0,
        width: requestWidth - requestPad,
        height: requestHeight,
      });
      const maskRgba = Buffer.alloc(requestWidth * requestHeight * 4, 0);
      for (let i = 0; i < requestWidth * requestHeight; i += 1) {
        maskRgba[i * 4 + 3] = maskRaw[i] > 127 ? 0 : 255;
      }
      const maskPng = await sharp(maskRgba, {
        raw: { width: requestWidth, height: requestHeight, channels: 4 },
      })
        .png()
        .toBuffer();

      const form = new FormData();
      form.append("model", "gpt-image-1");
      form.append("prompt", buildPrompt(analysis, plan, side));
      form.append("size", `${requestWidth}x${requestHeight}`);
      form.append("quality", quality === "draft" ? "medium" : "high");
      form.append("input_fidelity", "high");
      form.append("n", "1");
      form.append("image", new Blob([requestImage], { type: "image/png" }), "canvas.png");
      form.append("mask", new Blob([maskPng], { type: "image/png" }), "mask.png");

      const response = await fetch("https://api.openai.com/v1/images/edits", {
        method: "POST",
        headers: { Authorization: `Bearer ${key}` },
        body: form,
      });

      if (!response.ok) {
        throw new Error(`OpenAI ${response.status}: ${(await response.text()).slice(0, 400)}`);
      }

      const payload = await response.json();
      const b64 = payload?.data?.[0]?.b64_json;
      if (!b64) throw new Error("OpenAI returned no image data.");

      // Back to full resolution, then keep only the generated band.
      const full = await sharp(Buffer.from(b64, "base64"))
        .resize(windowWidth, meta.height, { fit: "fill", kernel: "lanczos3" })
        .png()
        .toBuffer();

      bands[side] = await sharp(full)
        .extract({
          left: side === "left" ? 0 : windowWidth - pad,
          top: 0,
          width: pad,
          height: meta.height,
        })
        .png()
        .toBuffer();
    }

    return bands;
  },
};

/**
 * Stability's outpaint endpoint extends the source natively from pixel amounts, in one call.
 * Input is capped at ~4MP, so we downscale for the request and lift the returned bands back
 * to full resolution. Only generated pixels are ever resampled.
 */
const stability = {
  id: "stability",
  label: "Stability AI stable-image/edit/outpaint",
  async generateSides({ image, meta, plan, analysis }) {
    const key = requireApiKey(["IMAGE_AI_API_KEY", "STABILITY_API_KEY"]);

    const MAX_PIXELS = 4_000_000;
    const scale = Math.min(1, Math.sqrt(MAX_PIXELS / (meta.width * meta.height)));
    const requestWidth = Math.round(meta.width * scale);
    const requestHeight = Math.round(meta.height * scale);
    const left = Math.round(plan.padding.left * scale);
    const right = Math.round(plan.padding.right * scale);

    if (left > 2000 || right > 2000) {
      throw new Error("Stability allows at most 2000px of outpaint per side. Lower --aspect.");
    }

    const requestImage = await sharp(image)
      .resize(requestWidth, requestHeight, { fit: "fill", kernel: "lanczos3" })
      .png()
      .toBuffer();

    const form = new FormData();
    form.append("image", new Blob([requestImage], { type: "image/png" }), "source.png");
    form.append("left", String(left));
    form.append("right", String(right));
    form.append("prompt", buildPrompt(analysis, plan, "both"));
    form.append("creativity", "0.35");
    form.append("output_format", "png");

    const response = await fetch("https://api.stability.ai/v2beta/stable-image/edit/outpaint", {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, Accept: "image/*" },
      body: form,
    });

    if (!response.ok) {
      throw new Error(`Stability ${response.status}: ${(await response.text()).slice(0, 400)}`);
    }

    const result = Buffer.from(await response.arrayBuffer());

    // Map the returned frame back onto the full-resolution plan and slice the two bands.
    const full = await sharp(result)
      .resize(plan.target.width, plan.target.height, { fit: "fill", kernel: "lanczos3" })
      .png()
      .toBuffer();

    const bands = {};
    if (plan.padding.left > 0) {
      bands.left = await sharp(full)
        .extract({ left: 0, top: 0, width: plan.padding.left, height: plan.target.height })
        .png()
        .toBuffer();
    }
    if (plan.padding.right > 0) {
      bands.right = await sharp(full)
        .extract({
          left: plan.target.width - plan.padding.right,
          top: 0,
          width: plan.padding.right,
          height: plan.target.height,
        })
        .png()
        .toBuffer();
    }

    return bands;
  },
};

/** Geometry/compositing check only — stretched context, no generation. Never ship this output. */
const dryRun = {
  id: "dry-run",
  label: "Dry run (no AI, geometry validation only)",
  async generateSides({ image, meta, plan }) {
    const bands = {};
    for (const side of ["left", "right"]) {
      const pad = plan.padding[side];
      if (pad <= 0) continue;
      const stretched = await stretchEdge(image, meta, side, pad, meta.height);
      bands[side] = await sharp(stretched).blur(24).png().toBuffer();
    }
    return bands;
  },
};

const PROVIDERS = { openai, stability, "dry-run": dryRun };

// ---------------------------------------------------------------------------
// compose + verify
// ---------------------------------------------------------------------------

/** The original is stamped last, at full resolution: the model never owns those pixels. */
async function composeWide(image, plan, bands) {
  const layers = [];
  if (bands.left) layers.push({ input: bands.left, left: 0, top: 0 });
  if (bands.right) layers.push({ input: bands.right, left: plan.target.width - plan.padding.right, top: 0 });
  layers.push({ input: await sharp(image).removeAlpha().png().toBuffer(), left: plan.placement.left, top: 0 });

  return sharp({
    create: { width: plan.target.width, height: plan.target.height, channels: 3, background: "#000000" },
  })
    .composite(layers)
    .png({ compressionLevel: 9 })
    .toBuffer();
}

/** Byte-level proof that the original region survived the round trip. */
async function verifyOriginal(widePng, image, plan) {
  const [region, original] = await Promise.all([
    sharp(widePng).extract(plan.placement).removeAlpha().raw().toBuffer(),
    sharp(image).removeAlpha().raw().toBuffer(),
  ]);

  if (region.length !== original.length) return { identical: false, diffPixels: -1 };

  let diffPixels = 0;
  for (let i = 0; i < region.length; i += 3) {
    if (region[i] !== original[i] || region[i + 1] !== original[i + 1] || region[i + 2] !== original[i + 2]) {
      diffPixels += 1;
    }
  }

  return { identical: diffPixels === 0, diffPixels };
}

// ---------------------------------------------------------------------------
// run
// ---------------------------------------------------------------------------

async function expandOne(name, args, provider) {
  const sourcePath = path.join(HERO_DIR, `${name}.jpg`);
  if (!existsSync(sourcePath)) throw new Error(`Missing source ${sourcePath}`);

  const outputPath = path.join(HERO_DIR, "expanded", `${name}-wide.jpg`);
  if (existsSync(outputPath) && !args.force) {
    return { name, skipped: true };
  }

  const image = readFileSync(sourcePath);
  const meta = await sharp(image).metadata();
  const plan = planExpansion(meta.width, meta.height, args.aspect);

  if (plan.padding.left + plan.padding.right === 0) {
    return { name, skipped: true, reason: "already at or wider than target aspect" };
  }

  const analysis = await analyzeImage(image, meta);
  const bands = await provider.generateSides({ image, meta, plan, analysis, quality: "high" });

  if (!bands.left && !bands.right) throw new Error("Provider returned no generated bands.");

  const widePng = await composeWide(image, plan, bands);
  const verification = await verifyOriginal(widePng, image, plan);

  if (!verification.identical) {
    throw new Error(
      `Original region was altered (${verification.diffPixels} pixels differ). Refusing to write.`,
    );
  }

  mkdirSync(path.dirname(outputPath), { recursive: true });
  await sharp(widePng).jpeg({ quality: JPEG_QUALITY, mozjpeg: true, chromaSubsampling: "4:4:4" }).toFile(outputPath);

  return {
    name,
    plan,
    output: path.relative(process.cwd(), outputPath),
    verified: true,
  };
}

async function main() {
  loadEnvLocal();
  const args = parseArgs(process.argv.slice(2));
  const provider = args.dryRun ? PROVIDERS["dry-run"] : resolveProvider(args.provider);
  const names = args.only ? [args.only] : HERO_IMAGES;

  console.log(`\nHero expansion — target aspect ${args.aspect}:1 via ${provider.label}\n`);

  let failures = 0;

  for (const name of names) {
    process.stdout.write(`  ${name} … `);
    try {
      const result = await expandOne(name, args, provider);

      if (result.skipped) {
        console.log(`skipped (${result.reason ?? "already generated, use --force"})`);
        continue;
      }

      const { source, target, padding } = result.plan;
      console.log(
        `${source.width}×${source.height} → ${target.width}×${target.height} ` +
          `(+${padding.left}L / +${padding.right}R) · original verified pixel-identical · ${result.output}`,
      );
    } catch (error) {
      failures += 1;
      console.log(`FAILED — ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  console.log(
    failures === 0
      ? "\nDone. The originals in imgs/hero were not modified.\n"
      : `\n${failures} image(s) failed. Originals untouched, existing hero unaffected.\n`,
  );

  process.exitCode = failures === 0 ? 0 : 1;
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
